113	fn verify(args: &[String]) -> ExitCode {
114	    // Argument errors follow the same conventions as `sign` (exit 2, message
115	    // that never echoes the key or any rejected value).
116	    let opts = match parse_verify_args(args) {
117	        Ok(opts) => opts,
118	        Err(msg) => {
119	            eprintln!("authnote verify: {msg}");
120	            return ExitCode::from(2);
121	        }
122	    };
123	
124	    // JSON is a byte-oriented text format: read raw bytes and require valid
125	    // UTF-8 rather than silently lossy-decoding the record.
126	    let mut input = Vec::new();
127	    if let Err(e) = std::io::stdin().read_to_end(&mut input) {
128	        eprintln!("authnote verify: failed to read standard input: {e}");
129	        return ExitCode::from(2);
130	    }
131	
132	    let outcome: Result<bool, String> = (|| {
133	        let record = parse_record(&input)?;
134	        let key_bytes = decode_hex(&opts.key).expect("key was validated as hex");
135	        let message = encode_message(&record.key_id, record.key_version, &record.fields);
136	        let mut mac = <Hmac<Sha256> as KeyInit>::new_from_slice(&key_bytes)
137	            .expect("HMAC accepts keys of any length");
138	        mac.update(&message);
